public class Main {
    static int H, W;
    static char[][] grid;

    static boolean isJOI(char a, char b, char c) {
        return a == 'J' && b == 'O' && c == 'I';
    }

    static int countAll() {
        int cnt = 0;
        for (int r = 0; r < H; r++)
            for (int c = 0; c + 2 < W; c++)
                if (isJOI(grid[r][c], grid[r][c+1], grid[r][c+2])) cnt++;
        for (int c = 0; c < W; c++)
            for (int r = 0; r + 2 < H; r++)
                if (isJOI(grid[r][c], grid[r+1][c], grid[r+2][c])) cnt++;
        return cnt;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        H = Integer.parseInt(st.nextToken());
        W = Integer.parseInt(st.nextToken());
        grid = new char[H][W];
        for (int i = 0; i < H; i++) grid[i] = br.readLine().toCharArray();

        int base = countAll();
        int best = base;

        char[] chars = {'J', 'O', 'I'};
        for (int r = 0; r < H; r++) {
            for (int c = 0; c < W; c++) {
                char orig = grid[r][c];
                for (char ch : chars) {
                    if (ch == orig) continue;
                    grid[r][c] = ch;
                    int total = countAll();
                    best = Math.max(best, total);
                    grid[r][c] = orig;
                }
            }
        }

        System.out.println(best);
    }
