public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int H = fs.nextInt();
        int W = fs.nextInt();

        char[][] oldFlag = new char[H][W];
        for (int i = 0; i < H; i++) oldFlag[i] = fs.next().toCharArray();

        int h = fs.nextInt();
        int w = fs.nextInt();

        char[][] emblem = new char[h][w];
        for (int i = 0; i < h; i++) emblem[i] = fs.next().toCharArray();

        int positions = (H - h + 1) * (W - w + 1);
        int baseCount = 0;

        int[][] gainJ = new int[H][W];
        int[][] gainO = new int[H][W];
        int[][] gainI = new int[H][W];

        for (int si = 0; si <= H - h; si++) {
            for (int sj = 0; sj <= W - w; sj++) {
                int mismatches = 0;
                int mi = -1, mj = -1;
                char need = 0;

                for (int i = 0; i < h; i++) {
                    for (int j = 0; j < w; j++) {
                        if (oldFlag[si + i][sj + j] != emblem[i][j]) {
                            mismatches++;
                            if (mismatches == 1) {
                                mi = si + i;
                                mj = sj + j;
                                need = emblem[i][j];
                            }
                        }
                    }
                }

                if (mismatches == 0) {
                    baseCount++;
                } else if (mismatches == 1) {
                    if (need == 'J') gainJ[mi][mj]++;
                    else if (need == 'O') gainO[mi][mj]++;
                    else if (need == 'I') gainI[mi][mj]++;
                }
            }
        }

        int answer = baseCount;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                answer = Math.max(answer, baseCount + gainJ[i][j]);
                answer = Math.max(answer, baseCount + gainO[i][j]);
                answer = Math.max(answer, baseCount + gainI[i][j]);
            }
        }

        System.out.println(answer);
    }
}

