    }
    for (int i = 0; i < H; i++) {
        B[i] = (char *)malloc((W + 1) * sizeof(char));
        scanf("%s", B[i]);
    }

    int h = 0, w = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (B[i][j] != '.') {
                if (i + 1 > h) h = i + 1;
                if (j + 1 > w) w = j + 1;
            }
        }
    }

    int outH = H - h + 1;
    int outW = W - w + 1;

    int **match = (int **)malloc(outH * sizeof(int *));
    for (int i = 0; i < outH; i++) {
        match[i] = (int *)calloc(outW, sizeof(int));
    }

    long long base = 0;

    for (int si = 0; si < outH; si++) {
        for (int sj = 0; sj < outW; sj++) {
            int ok = 1;
            for (int i = 0; i < h && ok; i++) {
                for (int j = 0; j < w; j++) {
                    if (B[i][j] == '.') continue;
                    if (A[si + i][sj + j] != B[i][j]) {
                        ok = 0;
                        break;
                    }
                }
            }
            match[si][sj] = ok;
            if (ok) base++;
        }
    }

    long long bestGain = 0;

    for (int x = 0; x < H; x++) {
        for (int y = 0; y < W; y++) {
            for (char c = 'A'; c <= 'Z'; c++) {
                if (c != 'J' && c != 'O' && c != 'I') continue;
                if (A[x][y] == c) continue;

                long long gain = 0;
                for (int si = x - h + 1; si <= x; si++) {
                    if (si < 0 || si >= outH) continue;
                    for (int sj = y - w + 1; sj <= y; sj++) {
                        if (sj < 0 || sj >= outW) continue;

                        int bi = x - si;
                        int bj = y - sj;
                        if (B[bi][bj] != c) continue;

                        int ok = 1;
                        for (int i = 0; i < h && ok; i++) {
                            for (int j = 0; j < w; j++) {
                                if (B[i][j] == '.') continue;
                                char ch = A[si + i][sj + j];
                                if (si + i == x && sj + j == y) ch = c;
                                if (ch != B[i][j]) {
                                    ok = 0;
                                    break;
                                }
                            }
                        }

                        if (ok && !match[si][sj]) gain++;
                    }
                }

                if (gain > bestGain) bestGain = gain;
            }
        }
    }

    printf("%lld\n", base + bestGain);

    for (int i = 0; i < H; i++) {
        free(A[i]);
        free(B[i]);
    }
    free(A);
    free(B);
    for (int i = 0; i < outH; i++) free(match[i]);
    free(match);

    return 0;
}

