int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S, T;
    cin >> S >> T;

    int n = (int)S.size();
    int m = (int)T.size();

    // Count occurrences of T in S initially.
    auto match_at = [&](int pos, const string& str) -> bool {
        if (pos < 0 || pos + m > n) return false;
        for (int i = 0; i < m; i++) {
            if (str[pos + i] != T[i]) return false;
        }
        return true;
    };

    int base = 0;
    for (int i = 0; i + m <= n; i++) {
        if (match_at(i, S)) base++;
    }

    int answer = base;

    // Try changing each position to J, O, or I.
    const string chars = "JOI";
    for (int p = 0; p < n; p++) {
        char original = S[p];

        // Only substrings starting in [p-m+1, p] can be affected.
        int L = max(0, p - m + 1);
        int R = min(p, n - m);

        int oldCnt = 0;
        for (int s = L; s <= R; s++) {
            if (match_at(s, S)) oldCnt++;
        }

        for (char c : chars) {
            if (c == original) {
                answer = max(answer, base);
                continue;
            }

            S[p] = c;

            int newCnt = 0;
            for (int s = L; s <= R; s++) {
                if (match_at(s, S)) newCnt++;
            }

            answer = max(answer, base - oldCnt + newCnt);
        }

        S[p] = original;
    }

    cout << answer << '\n';
    return 0;
}

