    # Expected emblem pattern
    pattern = [['J', 'O'], ['O', 'I']]

    # Precompute matches for each 2x2 position
    # For each cell (i,j) as top-left of 2x2
    perfect_count = 0
    # For positions with exactly 1 mismatch, we can fix it
    one_mismatch_positions = []

    for i in range(H - 1):
        for j in range(W - 1):
            mismatches = 0
            for di in range(2):
                for dj in range(2):
                    if grid[i+di][j+dj] != pattern[di][dj]:
                        mismatches += 1
            if mismatches == 0:
                perfect_count += 1
            elif mismatches == 1:
                one_mismatch_positions.append((i, j))

    # If we have at least one position with exactly 1 mismatch, 
    # we can fix it and also count all perfect ones.
    if one_mismatch_positions:
        # We need to see if fixing one cell can help more than one emblem.
        # However, we can only change one cell in the whole grid, 
        # so we must check overlapping positions.

        # Count how many perfect emblems we get if we change each candidate cell.
        # For each possible cell (r,c) in the grid, simulate change.
        best = perfect_count
        # Check each cell that could be changed
        for r in range(H):
            for c in range(W):
                # count emblems affected by this cell
                gain = 0
                # This cell can be part of up to 4 emblems (top-left, top-right, bottom-left, bottom-right)
                for di in (-1, 0):
                    for dj in (-1, 0):
                        ti = r + di
                        tj = c + dj
                        if 0 <= ti < H-1 and 0 <= tj < W-1:
                            mismatches = 0
                            for pi in range(2):
                                for pj in range(2):
                                    val = grid[ti+pi][tj+pj]
                                    if pi == r - ti and pj == c - tj:
                                        # This is the cell we might change
                                        # We can set it to the required pattern
                                        if pattern[pi][pj] != val:
                                            # fixing mismatch
                                            pass
                                        else:
                                            # already correct, no change needed
                                            pass
                                    else:
                                        if val != pattern[pi][pj]:
                                            mismatches += 1
                            if mismatches == 0:
                                gain += 1
                best = max(best, perfect_count + gain)
        print(best)
    else:
        # No single-change can help
        print(perfect_count)

